import React, { useState } from 'react';
import axios from 'axios';
import { getApiUrl } from '../utils/serverUrl';
import { useAuth } from '../context/AuthContext';
const API=getApiUrl();
export default function AITutorPage(){
 const {token}=useAuth(); const [q,setQ]=useState(''); const [answer,setAnswer]=useState(''); const [loading,setLoading]=useState(false); const [error,setError]=useState('');
 const ask=async(e)=>{e.preventDefault(); if(q.trim().length<2)return; setLoading(true);setError('');setAnswer(''); try{const r=await axios.post(`${API}/tutor/ask`,{question:q},{headers:{Authorization:`Bearer ${token}`}});setAnswer(r.data.answer||'No answer returned.');}catch(err){setError(err.response?.data?.message||'AI Tutor is unavailable. Check GEMINI_API_KEY on the server.');}finally{setLoading(false)}};
 return <div style={{minHeight:'100vh',padding:'110px 24px 60px'}}><div className="container" style={{maxWidth:900}}><div style={{marginBottom:28}}><span className="badge badge-purple">AI Learning</span><h1 style={{fontFamily:'var(--font-display)',fontWeight:800,fontSize:'clamp(2rem,5vw,3rem)',margin:'12px 0'}}>🤖 AI Tutor</h1><p style={{color:'var(--text-secondary)'}}>Ask concepts, request examples, or paste a topic you got wrong in a quiz.</p></div><form onSubmit={ask} className="glass-card" style={{padding:20,display:'flex',gap:12,alignItems:'stretch',flexWrap:'wrap'}}><textarea value={q} onChange={e=>setQ(e.target.value)} placeholder="Example: Explain database normalization with a simple example..." rows={4} style={{flex:'1 1 560px',minWidth:0,padding:16,borderRadius:14,border:'1px solid var(--border)',background:'rgba(255,255,255,.04)',color:'var(--text-primary)',resize:'vertical'}}/><button className="btn btn-primary" disabled={loading||q.trim().length<2}>{loading?'Thinking...':'Ask AI'}</button></form>{error&&<div className="glass-card" style={{padding:16,marginTop:16,color:'#ff9999'}}>{error}</div>}{answer&&<div className="glass-card" style={{padding:28,marginTop:20}}><div className="badge badge-green">AI Explanation</div><div style={{whiteSpace:'pre-wrap',lineHeight:1.7,color:'var(--text-primary)',marginTop:16}}>{answer}</div></div>}<div style={{display:'flex',gap:10,flexWrap:'wrap',marginTop:18}}>{['Explain React hooks simply','What is DBMS normalization?','Explain TCP vs UDP','Give me a Python practice problem'].map(x=><button key={x} className="btn btn-secondary" onClick={()=>setQ(x)}>{x}</button>)}</div></div></div>;
}
